import pytest
import requests

# Base URL for the API
BASE_URL = "http://api.example.com/2.1/nobelPrize"

# Test configuration options
@pytest.fixture(scope="module")
def config():
    return {
        "base_url": BASE_URL,
        "valid_category": "physics",
        "valid_year": 2020,
        "invalid_category": "invalidCategory",
        "invalid_year": 1800  # Invalid since the minimum year is 1901
    }

# Helper function to generate endpoint URL
def build_url(base_url, category, year):
    return f"{base_url}/{category}/{year}"

# Test for valid Nobel Prize
def test_get_nobel_prize_success(config):
    """Test a valid request to fetch Nobel Prize details."""
    url = build_url(config["base_url"], config["valid_category"], config["valid_year"])
    response = requests.get(url)

    assert response.status_code == 200
    json_response = response.json()
    assert "nobelPrize" in json_response

    # Validate specific fields in the response
    assert json_response["nobelPrize"]["awardYear"] == config["valid_year"]
    assert json_response["nobelPrize"]["category"]["en"].lower() == config["valid_category"]

# Test for 400 - Bad Request
@pytest.mark.parametrize(
    "category,year",
    [
        ("", 2020),  # Missing category
        ("physics", ""),  # Missing year
    ]
)
def test_get_nobel_prize_bad_request(config, category, year):
    """Test requests that should produce a 400 Bad Request response."""
    url = build_url(config["base_url"], category, year)
    response = requests.get(url)

    assert response.status_code == 400
    json_response = response.json()
    assert json_response["code"] == "400"
    assert "message" in json_response

# Test for 404 - Not Found
def test_get_nobel_prize_not_found(config):
    """Test request for invalid category/year combination which should return 404."""
    url = build_url(config["base_url"], config["invalid_category"], config["valid_year"])
    response = requests.get(url)

    assert response.status_code == 404
    json_response = response.json()
    assert json_response["code"] == "404"
    assert "message" in json_response

# Test for 422 - Unprocessable Entity
