def test_get_nobel_prize_unprocessable_entity(config, category, year):
    """Test requests that should produce a 422 Unprocessable Entity response."""
    url = build_url(config["base_url"], category, year)
    response = requests.get(url)

    assert response.status_code == 422
    json_response = response.json()
    assert json_response["code"] == "422"
    assert "message" in json_response

